SELECT percentile_cont(0.25) within GROUP (ORDER BY r.value) AS q25, percentile_cont(0.50) within GROUP (ORDER BY r.value) AS q50, percentile_cont(0.75) within GROUP (ORDER BY r.value) AS q75 FROM (SELECT s.hadm_id, s.stay_id, p.gender, p.age, d.icd_code, d.icd_version, r.value, c.careunit FROM subjects s JOIN admissions a ON s.subject_id = a.subject_id JOIN patients p ON s.subject_id = p.subject_id JOIN diagnoses_icd d ON a.hadm_id = d.hadm_id JOIN chartevents c ON a.hadm_id = c.hadm_id AND a.stay_id = c.stay_id AND c.itemid = 17161 AND c.value = 'Radiography' OR c.value = 'CT' JOIN (SELECT hadm_id, stay_id, value FROM chartevents WHERE itemid = 17161 AND value IN ('Radiography', 'CT')) r ON a.hadm_id = r.hadm_id AND a.stay_id = r.stay_id WHERE p.gender = 'M' AND p.age BETWEEN 59 AND 69 AND d.icd_code = '440.91' AND d.icd_version = '2015' AND (s.stay_id BETWEEN 1 AND 4 OR s.stay_id BETWEEN 5 AND 8)) subquery;